import{_ as t,o as a,c as l,a5 as n}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"853-读取excell核对指定列内尺寸信息是否正确","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["EXCEL批处理"],"标签":["Excel顺序比对","异常标黄","批量处理","数据检查","表格校验"]},"headers":[{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[]},{"level":3,"title":"数据存储位置","slug":"数据存储位置","link":"#数据存储位置","children":[]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"程序截图","slug":"程序截图","link":"#程序截图","children":[]},{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}],"relativePath":"md/EXCEL批处理/853-读取excell核对指定列内尺寸信息是否正确.md","filePath":"md/EXCEL批处理/853-读取excell核对指定列内尺寸信息是否正确.md"}'),r={name:"md/EXCEL批处理/853-读取excell核对指定列内尺寸信息是否正确.md"};function o(s,e,p,i,c,h){return a(),l("div",null,[...e[0]||(e[0]=[n('<p>检测指定列综合数据与指定的其他两列数据是否匹配，不匹配则自动标黄正行，以便人工核验数据。</p><p>检查 Excel 中指定单元格内数据尺寸是否正确。在程序上选好第一个指定列、第二个指定列和比对列，点一下按钮，就能自动检查比对列里是否按照先 A 后 B 的顺序出现，并把不符合的整行标黄以便查看是否正确，方便你一眼看出问题行。</p><p>上手非常简单，双击启动即可使用。<strong>自动逐行比对数据，发现不符合的行直接标成黄色</strong>。处理时保留原有单元格格式，结果保存回原表。拖拽 Excel 文件到窗口也能快速导入。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208181054176518865461579.png" alt=""></p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><p>先选择要处理的 Excel 文件，支持 xlsx。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208181508176518890874084.png" alt=""></p><p>设置 第一个指定列、第二个指定列和比对列，默认 A、B、L，可根据实际表格列调整。</p><p>设定起始行，通常从第 2 行开始跳过表头。</p><p>确认后点击开始处理，进度条会显示完成度。</p><p>处理完成后，原表里不符合的行会被标黄，日志窗口会提示结果。</p><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><p>如果需要核对指定C列商品尺寸描述是否正确（比如：850<em>150）：把850位于A列，150位于B列，把描述放在比对列C，运行后工具会检查描述里的850</em>150是否正确，如果不正确则会自动将改行标黄，以便后续核对。</p><h3 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h3><p>工具只读取并写回你选择的 Excel 文件，保留原有格式。不符合顺序的行仅改变填充颜色为黄色，其他格式不变。</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>处理前务必先备份原始文件。列名要用英文字母表示，如 A、B、L。文件路径和文件名尽量避免特殊符号。处理过程中不要关闭工具或占用表格，避免保存失败。文件过大时可分批处理，减轻等待时间。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q 双击后没有反应怎么办？</strong><br> A 确认系统是 Windows 64 位且文件已完整解压，检查安全软件是否拦截，必要时将程序添加到信任名单再试。</p><p><strong>Q 选择文件时找不到我的表格怎么办？</strong><br> A 确认文件扩展名是 xlsx，确保文件未被其他软件占用，路径和名称不要包含特殊符号。</p><p><strong>Q 结果里整行变黄代表什么？</strong><br> A 说明比对列中未按先 A ，后 B 的顺序找到对应值，该行需要人工检查。</p><p><strong>Q 想跳过表头应该怎么设？</strong><br> A 将起始行改为 2，从第二行开始处理数据。</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208181852176518913231893.png" alt=""></p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后，直接运行该快捷方式即可，快捷方式可以放到任意位置</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208182814176518969473174.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2234.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2234.html</a></p>',34)])])}const _=t(r,[["render",o]]);export{d as __pageData,_ as default};
